def do_block(parser, token):
    """
    Process several nodes inside a single block
    Block functions take ``context``, ``nodelist`` as first arguments
    If the second to last argument is ``as``, the rendered result is stored in the context and is named whatever the last argument is.

    Syntax::

        {% [block] [var args...] [name=value kwargs...] [as varname] %}
            ... nodelist ...
        {% end[block] %}

    Examples::

        {% render_block as rendered_output %}
            {{ request.path }}/blog/{{ blog.slug }}
        {% endrender_block %}

        {% highlight_block python %}
            import this
        {% endhighlight_block %}

    """
    %}
            {% block as rendered %}
                ... nodelist ...
            {% endblock %}

        """
        bits = token.split_contents()
        args = bits[1:-1]
        kwargs = bits[-1]
        if not args and not kwargs:
            raise template.TemplateSyntaxError('do_block requires at least one argument')
        if kwargs.startswith('as'):
            name = kwargs[2:]
            if name:
                raise template.TemplateSyntaxError('do_block: The last argument must be "as varname"')
        else:
            name = None
        nodelist = parser.parse(('end' + bits[0],))
        parser.delete_first_token()
        return BlockNode(nodelist, args, kwargs, name)

